mapper.select:
select #{VALID_STATUS_01} VALID_STATUS, wtrd.TRADE_ID, wtrda.ENTRUST_ID, pp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fpa.BOARD, wtrd.PS, wtrda.DEAL_MODE, fpa.FINPROD_ID, wtrd.TRADE_MARKET, wtrd.TRADE_DATE, wtrd.UNIT_CPRICE, wtrd.SHARE_AMT, wtrd.TRADE_AMT, wtrd.CCY, wtrd.REMARK, wtrd.WORKFLOW_ID , wtrd.workflow_status from WFL_TRD_PRODUCT_DEAL wtrd left join WFL_TRD_PRODUCT_DEAL_ADD wtrda on wtrd.TRADE_ID = wtrda.TRADE_ID left join FIN_PRODUCT fp on wtrd.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID = fp.FINPROD_ID left join PTL_PORTFOLIO pp on wtrda.PORTFOLIO_ID = pp.PORTFOLIO_ID where pp.INVEST_YESORNO='Y' and fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} AND wtrd.TRADE_STATUS =#{VALID_STATUS_01}
AND wtrd.PS IN
#{item}
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
AND wtrd.FINPROD_ID IN
#{item}
AND wtrd.FINPROD_MARKET_ID IN
#{item}
AND wtrd.TRADE_MARKET IN
#{item}
AND wtrd.PS IN
#{item}
AND wtrda.DEAL_MODE IN
#{item}
AND fpa.BOARD IN
#{item}
AND wtrd.CCY IN
#{item}
AND wtrda.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
AND fpa.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
AND trd.TRADER IN
#{item}
AND wtrd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND wtrd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and #{VALID_STATUS_01} = #{validStatus}
UNION ALL select
decode(trd.IS_CANCEL,#{YES_NO_YES},#{VALID_STATUS_03},#{YES_NO_NO},#{VALID_STATUS_02},#{VALID_STATUS_02}) as VALID_STATUS, trd.TRADE_ID, tpda.ENTRUST_ID, PP.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fpa.BOARD, trd.PS, tpda.DEAL_MODE, fpa.FINPROD_ID, trd.TRADE_MARKET, trd.TRADE_DATE, trd.UNIT_CPRICE, trd.SHARE_AMT, trd.TRADE_AMT, trd.CCY, trd.REMARK, null WORKFLOW_ID , null workflow_status from TRD_PRODUCT_DEAL trd left join TRD_PRODUCT_DEAL_ADD tpda on trd.TRADE_ID = tpda.TRADE_ID left join FIN_PRODUCT fp on trd.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID = fp.FINPROD_ID LEFT JOIN PTL_TRADE PT ON nvl(trd.P_TRADE_ID,trd.TRADE_ID) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID where PP.INVEST_YESORNO = 'Y' AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10}
AND trd.PS IN
#{item}
AND (trd.IS_CANCEL is null or trd.IS_CANCEL = #{YES_NO_NO})
AND trd.IS_CANCEL = #{YES_NO_YES}
AND ( #{validStatus} =#{VALID_STATUS_02} or #{validStatus} =#{VALID_STATUS_03} )
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
AND trd.FINPROD_ID IN
#{item}
AND fp.FINPROD_MARKET_ID IN
#{item}
AND trd.TRADE_MARKET IN
#{item}
AND trd.PS IN
#{item}
AND tpda.DEAL_MODE IN
#{item}
AND fpa.BOARD IN
#{item}
AND trd.CCY IN
#{item}
AND tpda.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
AND fpa.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
AND trd.TRADER IN
#{item}
AND trd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND trd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and trd.P_TRADE_ID is null ORDER BY TRADE_ID DESC

SELECT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
A.PORTFOLIO_ID = #{portfolioId}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND B.TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}
UNION ALL SELECT SEC_ACCT_ID hidCode, SEC_ACCT_ID code, SEC_ACCT_NAME name, SEC_ACCT_NAME shortName FROM STL_SEC_ACCT_INFO

SELECT
ACCT_NO
FROM
PTL_CAPACCT_INFO
WHERE
ACCT_TYPE = #{ACCT_TYPE}
AND CCY = #{ccy}
AND
PORTFOLIO_ID = #{portfolioId}

SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID, A.FINPROD_ID, A.FINPROD_NAME text, A.TRADE_MARKET, A.CCY, b.board FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B on a.finprod_id=b.finprod_id where A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
and ( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
and ( A.FINPROD_MARKET_ID =#{initValue} or A.FINPROD_NAME =#{initValue} or A.FINPROD_ID =#{initValue} )

select
  AMOUNT
from PTL_CASH_POSITION
where
	(HODING_TYPE=#{POSITION_TYPE_01} or HODING_TYPE=#{POSITION_TYPE_03}) and PORTFOLIO_ID=#{portfolioId}
	and CDATE=(select cur_date from sys_date) and CHL_FINPROD_ID=#{TongDao}
